package com.example.mediqueue.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="prescriptions") public class Prescription{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(optional=false) @JoinColumn(name="patient_id") Patient patient;@ManyToOne @JoinColumn(name="doctor_id") Doctor doctor;@ManyToOne @JoinColumn(name="appointment_id") Appointment appointment;@Column(length=5000) String medicines;@Column(length=2000) String instructions;LocalDateTime createdAt=LocalDateTime.now();public Prescription(){}public Long getId(){return id;}public Patient getPatient(){return patient;}public void setPatient(Patient p){patient=p;}public Doctor getDoctor(){return doctor;}public void setDoctor(Doctor d){doctor=d;}public Appointment getAppointment(){return appointment;}public void setAppointment(Appointment a){appointment=a;}public String getMedicines(){return medicines;}public void setMedicines(String m){medicines=m;}public String getInstructions(){return instructions;}public void setInstructions(String i){instructions=i;}public LocalDateTime getCreatedAt(){return createdAt;}}
